import {test} from 'node:test';
import assert from 'node:assert/strict';
import {episodeExample} from '../examples/episode.js';
import {createProjectBundle,readProjectBundle,inspectRaster} from '../src/project-bundle.js';
const png=Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aF1EAAAAASUVORK5CYII='),c=>c.charCodeAt(0)),blob=new Blob([png],{type:'image/png'});
function project(){const p=structuredClone(episodeExample);for(const s of p.shots)s.reference={id:'ref-shared',name:'Original art.png',time:1};p.shots[0].actors.ona={clip:'wave',offset:0,speed:1,pose:{'head.rotation':[[0,0],[1,10]]},expressions:[[0,'happy']]};return p;}
test('portable project deduplicates images and preserves complete scene and authored take data',async()=>{const p=project(),bundle=await createProjectBundle(p,async()=>blob);assert.equal(bundle.assets.length,1);const read=await readProjectBundle(JSON.stringify(bundle));assert.deepEqual(read.project,p);assert.deepEqual(new Uint8Array(await read.assets.get('ref-shared').arrayBuffer()),png);read.project.name='Changed';assert.notEqual(p.name,read.project.name);});
test('missing references cannot silently create or open an incomplete portable project',async()=>{await assert.rejects(createProjectBundle(project(),async()=>undefined),/Missing reference images: ref-shared/);const b=await createProjectBundle(project(),async()=>blob);b.assets=[];await assert.rejects(readProjectBundle(b),/Missing bundled reference/);});
test('corrupt, executable, mismatched, duplicate and oversized image assets are rejected',async()=>{const bundle=await createProjectBundle(project(),async()=>blob);for(const change of [b=>b.assets[0].sha256='0'.repeat(64),b=>b.assets[0].type='image/svg+xml',b=>b.assets.push(b.assets[0]),b=>b.assets[0].bytes=20000001,b=>b.assets[0].data='!'.repeat(b.assets[0].data.length),b=>b.assets[0].id='unreferenced']){const b=structuredClone(bundle);change(b);await assert.rejects(readProjectBundle(b));}const large=png.slice();new DataView(large.buffer).setUint32(16,60000);assert.throws(()=>inspectRaster(large,'image/png'),/4096/);await assert.rejects(createProjectBundle(project(),async()=>new Blob(['<svg/>'],{type:'image/png'})),/Invalid PNG/);});
test('image decode validation finishes before bundle assets are exposed',async()=>{const b=await createProjectBundle(project(),async()=>blob);await assert.rejects(readProjectBundle(b,{validateImage:async()=>{throw new Error('decoder rejected');}}),/decoder rejected/);});
test('empty-media projects work and malformed episode keys remain rejected',async()=>{const p=structuredClone(episodeExample);const b=await createProjectBundle(p,async()=>{throw new Error('unused');});assert.equal(b.assets.length,0);assert.deepEqual((await readProjectBundle(b)).project,p);b.project.shots[0].camera.zoom=[[0,-1]];await assert.rejects(readProjectBundle(b),/keyframes/);});
